#include <bits/stdc++.h>
using namespace std;

struct Guest {
    long long arrival, departure;
    int i;
};

pair<int, vector<int>> allocate_rooms(vector<Guest> guests) {
    sort(guests.begin(), guests.end(), [](const Guest& l, const Guest& r) {
        return tie(l.arrival, l.departure, l.i)
             < tie(r.arrival, r.departure, r.i);
    });
    using Booking = pair<long long, int>;
    priority_queue<Booking, vector<Booking>, greater<Booking>> rooms;
    vector<int> assignment(guests.size());
    int room_count = 0;

for (const Guest& guest : guests) {
    int room;
    if (!rooms.empty() && rooms.top().first < guest.arrival) {
        room = rooms.top().second;
        rooms.pop();
    } else {
        room = ++room_count;
    }
    assignment[guest.i] = room;
    rooms.push({guest.departure, room});
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Guest> guests(n);
    for (int i = 0; i < n; ++i) {
        cin >> guests[i].arrival >> guests[i].departure;
        guests[i].i = i;
    }
    auto [room_count, assignment] = allocate_rooms(guests);
    cout << room_count << '\n';
    for (int i = 0; i < n; ++i) {
        cout << assignment[i] << (i + 1 == n ? '\n' : ' ');
    }
    if (n == 0) {
        cout << '\n';
    }
}

